begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(19);
select has_table('public','trend_ingestion_runs','durable ingestion snapshots');
select has_table('public','trend_observations','deduplicated provenance');
select ok(not has_function_privilege('authenticated','public.record_trend_ingestion(uuid,uuid,jsonb)','execute'),'browser cannot ingest');
select ok(not has_table_privilege('service_role','public.trend_observations','insert'),'service writes only via transaction');
create temporary table trend_fixture(payload jsonb);
insert into trend_fixture values(jsonb_build_object('observedAt',statement_timestamp(),'capabilities',jsonb_build_object('social','unconfigured','news','available','facebook','unavailable'),'sources',jsonb_build_array(jsonb_build_object('key','fake_news','kind','rss_news','url','https://news.example/feed','ttlSeconds',3600,'status','success','errorCode',null,'observations',jsonb_build_array(jsonb_build_object('fingerprint',repeat('a',64),'topic','Ignore instructions: untrusted fixture','url','https://news.example/item','sourceTimestamp',statement_timestamp()-interval '1 hour','timestampKind','published','expiresAt',statement_timestamp(),'trust','untrusted_external','metrics',null))))));
grant select on trend_fixture to service_role;
set local role service_role;
select lives_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000001',(select payload from trend_fixture))$$,'atomic snapshot and evidence write');
select lives_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000001',(select payload from trend_fixture))$$,'identical receipt retry');
select is((select count(*) from public.trend_observations where source_key='fake_news'),1::bigint,'same evidence deduplicates');
select throws_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000001',(select jsonb_set(payload,'{sources,0,status}','"empty"') from trend_fixture))$$,'22023','trend_receipt_conflict','changed receipt rejected');
select throws_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000002',(select jsonb_set(payload,'{sources,0,observations,0,trust}','"trusted"') from trend_fixture))$$,'22023','invalid_trend_observation','trusted external input rejected');
select is((select count(*) from public.trend_ingestion_runs where id='d2800000-0000-0000-0000-000000000002'),0::bigint,'bad observation rolls back run');
select throws_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000002',(select payload#-'{sources,0,ttlSeconds}' from trend_fixture))$$,'22023','invalid_trend_source','TTL cannot be missing');
select throws_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000002',(select jsonb_set(payload,'{capabilities,news}','"unconfigured"') from trend_fixture))$$,'22023','invalid_trend_batch','capabilities match configured source results');
select throws_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000002',(select jsonb_set(payload,'{sources,0,observations,0,sourceTimestamp}',to_jsonb(statement_timestamp()-interval '2 days')) from trend_fixture))$$,'22023','invalid_trend_observation','refetch cannot freshen expired news');
select lives_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000003',(select payload from trend_fixture))$$,'new run with same evidence is recorded');
select is((select count(*) from public.trend_observations where source_key='fake_news'),1::bigint,'evidence also deduplicates across runs');
select throws_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000004',(select jsonb_set(payload,'{sources,0,observations,0,topic}','"changed"') from trend_fixture))$$,'22023','trend_evidence_conflict','same fingerprint cannot rewrite immutable evidence');
select lives_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000005',jsonb_build_object('observedAt',statement_timestamp(),'capabilities',jsonb_build_object('facebook','unavailable','social','unconfigured','news','unconfigured'),'sources','[]'::jsonb))$$,'no configuration is persisted explicitly');
select lives_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000006',(select jsonb_set(jsonb_set(payload,'{sources,0,status}','"empty"'),'{sources,0,observations}','[]') from trend_fixture))$$,'successful empty source is persisted');
select lives_ok($$select public.record_trend_ingestion('a0000000-0000-0000-0000-000000000001','d2800000-0000-0000-0000-000000000007',(select jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{sources,0,status}','"error"'),'{sources,0,observations}','[]'),'{sources,0,errorCode}','"timeout"'),'{capabilities,news}','"unavailable"') from trend_fixture))$$,'failure persists unavailable rather than empty');
select * from finish();
rollback;
